import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BS0bAV7E.js";const g=JSON.parse('{"title":"Internals: the watchdog subsystem","description":"","frontmatter":{},"headers":[],"relativePath":"internals/watchdog.md","filePath":"internals/watchdog.md"}'),r={name:"internals/watchdog.md"};function n(h,e,i,l,d,c){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="internals-the-watchdog-subsystem" tabindex="-1">Internals: the watchdog subsystem <a class="header-anchor" href="#internals-the-watchdog-subsystem" aria-label="Permalink to &quot;Internals: the watchdog subsystem&quot;">​</a></h1><p><code>kernel/core/core_watchdog.{c,h}</code> - two watchdog worlds, one header.</p><h2 id="policy-watchdogs-monitored-slots" tabindex="-1">Policy watchdogs (monitored slots) <a class="header-anchor" href="#policy-watchdogs-monitored-slots" aria-label="Permalink to &quot;Policy watchdogs (monitored slots)&quot;">​</a></h2><p>A task registers a slot with a timeout:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>slot = watchdog_register(&quot;mydaemon&quot;, 5000, policy);</span></span>
<span class="line"><span>watchdog_start(slot);</span></span>
<span class="line"><span>... watchdog_feed(slot);   /* at least every 5 s */</span></span></code></pre></div><p>Timeout fires -&gt; the TASK is killed, the reason lands in the kernel log (<code>test log ERROR</code> in the E2E), the KERNEL lives on. This is the right tool for &quot;my background worker may hang&quot;.</p><h2 id="hardware-watchdogs" tabindex="-1">Hardware watchdogs <a class="header-anchor" href="#hardware-watchdogs" aria-label="Permalink to &quot;Hardware watchdogs&quot;">​</a></h2><ul><li><strong>Intel TCO</strong> (LPC): PMBASE discovered from the chipset, TCOBASE derived, the timer armed; expiry hard-resets the machine. Live on QEMU q35 - the E2E S12 prints the discovery line, arms, starves, and asserts the REAL second boot.</li><li><strong>ACPI WDAT</strong>: the table&#39;s entries program the hardware; same verify-by-reboot cycle (E2E S13).</li></ul><p><code>watchdog</code> shows both worlds: hardware support + slot table + policy tests.</p><h2 id="the-e2e-scenarios-that-gate-this" tabindex="-1">The E2E scenarios that gate this <a class="header-anchor" href="#the-e2e-scenarios-that-gate-this" aria-label="Permalink to &quot;The E2E scenarios that gate this&quot;">​</a></h2><p>S7 (status/slots), S8 (policy kill + log), S12 (TCO real reset + second boot), S13 (WDAT real reset + second boot). Fourteen total in <code>tools/wp12_watchdog_logging_e2e.py</code> - all fourteen must PASS at release.</p>`,11)])])}const m=t(r,[["render",n]]);export{g as __pageData,m as default};
